<script setup>
import { reactive, ref } from 'vue'
import { account, saveProfile, updatePassword, savePreferences } from '../domain/account.js'
const props=defineProps({mode:String}),emit=defineEmits(['done','message','close'])
const user=account.user,profile=reactive({displayName:user.displayName,email:user.email||'',phone:user.phone||'',bio:user.bio||''}),password=reactive({current:'',next:'',confirm:''}),preferences=reactive({...user.preferences}),error=ref(''),busy=ref(false)
async function save(){error.value='';busy.value=true;try{if(props.mode==='profile')await saveProfile(profile);if(props.mode==='password'){if(password.next!==password.confirm)throw Error('两次输入的新密码不一致。');await updatePassword(password.current,password.next);password.current='';password.next='';password.confirm='';emit('close');return}if(props.mode==='preferences')await savePreferences(preferences);emit('done',props.mode==='preferences'?'显示设置已保存，将用于下次登录。':'个人资料已保存。')}catch(e){error.value=e.message}finally{busy.value=false}}
</script>
<template><form class="account-form" @submit.prevent="save"><p v-if="error" class="form-error" role="alert">{{error}}</p><template v-if="mode==='profile'"><div class="account-summary"><span class="profile-avatar-large">{{Array.from(user.displayName)[0]}}</span><div><strong>{{user.displayName}}</strong><p>{{user.username}} · 管理员</p></div></div><div class="account-field-grid"><label>登录账号<input :value="user.username" readonly/></label><label>角色<input value="管理员" readonly/></label><label class="full-field">显示名称 <b>*</b><input v-model="profile.displayName" required maxlength="60" autocomplete="name"/></label><label>邮箱<input v-model="profile.email" type="email" maxlength="160" autocomplete="email" placeholder="选填"/></label><label>联系电话<input v-model="profile.phone" maxlength="24" autocomplete="tel" placeholder="选填"/></label><label class="full-field">个人说明<textarea v-model="profile.bio" rows="3" maxlength="300"/></label></div><p class="form-hint">只修改当前登录账号资料，登录账号和管理员角色不可在此修改。</p></template><template v-else-if="mode==='password'"><p class="password-notice">修改后所有旧会话会失效，需要重新登录。</p><label>原密码<input v-model="password.current" type="password" required autocomplete="current-password" maxlength="64"/></label><label>新密码<input v-model="password.next" type="password" required autocomplete="new-password" minlength="10" maxlength="64"/></label><label>确认新密码<input v-model="password.confirm" type="password" required autocomplete="new-password" minlength="10" maxlength="64"/></label><p class="form-hint">10～64 个字符，须包含字母和数字，可使用符号；不能与原密码相同。</p></template><template v-else><label>全局字号<select v-model="preferences.fontSize"><option value="normal">标准字号</option><option value="large">较大字号</option><option value="xlarge">大字号</option></select></label><label>表格密度<select v-model="preferences.density"><option value="comfortable">标准行距</option><option value="compact">紧凑行距</option></select></label><p class="form-hint">字号应用于导航、表单、表格、卡片和图表，并随当前账号保存。</p></template><footer class="account-form-actions"><button class="outline-button" type="button" @click="emit('close')">取消</button><button class="soft-button active" :disabled="busy" type="submit">{{busy?'正在保存…':mode==='password'?'确认修改密码':'保存'}}</button></footer></form></template>
